// 复习界面草稿：独立示例题库，内存状态，无模型批阅和持久化。
const reviewSamples=[
{subject:'数学',topic:'分数除法',question:'计算：3/4 ÷ 1/2',reason:'上次仍不会',hint:'除以一个非零分数，可以转化为乘以它的倒数。',answer:'3/4 × 2 = 3/2'},
{subject:'语文',topic:'修改病句',question:'修改病句：通过这次活动，使我明白了合作的重要性。',reason:'上次提示后做对',hint:'检查句子中有没有明确的主语。',answer:'示例改法：这次活动使我明白了合作的重要性。'},
{subject:'数学',topic:'分数加法',question:'计算：1/3 + 1/4',reason:'较久未复习',hint:'分母不同时，先通分。',answer:'1/3 + 1/4 = 4/12 + 3/12 = 7/12'},
{subject:'语文',topic:'修辞判断',question:'“弯弯的月亮像一只小船。”这句话运用了什么修辞手法？这样写有什么作用？',reason:'上次遗漏了第二问',hint:'题目要求回答修辞手法和表达作用两个部分。',answer:'运用了比喻，把月亮比作小船，生动形象地写出了月亮弯弯的形状。符合题意的其他表达也可。'},
{subject:'数学',topic:'小数计算',question:'计算：0.6 × 0.25',reason:'已掌握 · 穿插检查',hint:'先按整数相乘，再判断小数位数。',answer:'0.6 × 0.25 = 0.15'},
{subject:'数学',topic:'解方程',question:'解方程：3x + 6 = 21',reason:'上次提示后做对',hint:'先让等式两边同时减去 6。',answer:'3x = 15，x = 5'},
{subject:'语文',topic:'词语辨析',question:'选择合适的词语：即使遇到困难，我们也要（坚持 / 坚固）下去。',reason:'较久未复习',hint:'想一想，这里需要表示继续行动，还是表示结实。',answer:'坚持。'}
];
let reviewOrder=reviewSamples.map((_,i)=>i),reviewSelected=new Set(),reviewQueue=[],reviewIndex=0,reviewHint=false,reviewResults=[];
function reviewShell(subtitle){view='复习';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('heading').textContent='复习';$('subheading').textContent=subtitle;$('composer').hidden=true;$('panel').hidden=true;$('toggle').hidden=true;}
function reviewHome(){reviewShell('自己决定什么时候开始');$('chat').innerHTML='<div class="notice">复习交互草稿 · 使用独立的示例题库，不代表你的实际错题数量；未接入模型，不保存数据。</div><h2 class="viewtitle">准备好，再开始</h2><p>点击后查看推荐清单，可以换题、增减，再决定开始。</p><button class="primary" data-review="recommend">推荐复习 →</button>';}
function reviewList(reset=true){reviewShell('推荐清单 · 示例数据');if(reset)reviewSelected=new Set(reviewOrder.slice(0,5));$('chat').innerHTML='<div class="notice">演示推荐清单：每次默认选中 5 题。实际推荐算法尚未实现。</div><h2>这次想练哪些题？</h2><p class="muted">优先巩固困难题，也穿插检查已掌握题。可以自行增减。</p>'+reviewOrder.map(i=>{const q=reviewSamples[i];return '<div class="item"><label style="display:flex;gap:12px;align-items:flex-start;cursor:pointer"><input type="checkbox" data-review-check="'+i+'" '+(reviewSelected.has(i)?'checked':'')+' style="margin-top:7px"><span><span class="tag">'+q.subject+' · '+q.topic+'</span><span class="tag state">'+q.reason+'</span><span style="display:block;margin-top:10px">'+formattedText(q.question)+'</span></span></label></div>';}).join('')+'<div class="actions"><button class="primary" id="beginReview" data-review="begin">开始复习（'+reviewSelected.size+' 题）</button><button data-review="replace">换一组</button><button data-review="home">暂不开始</button></div>';$('chat').scrollTop=0;}
function reviewQuestion(){reviewShell('独立作答 · 第 '+(reviewIndex+1)+' 题，共 '+reviewQueue.length+' 题');reviewHint=false;const q=reviewSamples[reviewQueue[reviewIndex]];$('chat').innerHTML='<div class="notice">原答案和错因分析已隐藏。本演示不调用模型批阅。</div><span class="tag">'+q.subject+' · '+q.topic+'</span><h2>先试着自己完成</h2><div class="paper" style="font-size:19px;margin:20px 0">'+formattedText(q.question)+'</div><label for="reviewAnswer">我的答案与解题过程</label><textarea class="editable" id="reviewAnswer" style="margin-top:10px;min-height:150px" placeholder="输入答案和思路；分数可用 3/4 表示"></textarea><div id="answerPreview" class="muted"></div><div id="reviewHint"></div><div class="actions" style="margin-top:18px"><button class="primary" data-review="submit">提交作答</button><button data-review="hint">给我提示</button><button data-review="list">返回选题</button></div><div id="reviewFeedback"></div>';$('chat').scrollTop=0;}
document.addEventListener('input',e=>{if(e.target.id==='reviewAnswer'){$('answerPreview').innerHTML=formattedText(e.target.value).replace(/\n/g,'<br>');}});
document.addEventListener('change',e=>{if(!e.target.hasAttribute('data-review-check'))return;const i=Number(e.target.dataset.reviewCheck);e.target.checked?reviewSelected.add(i):reviewSelected.delete(i);$('beginReview').disabled=reviewSelected.size===0;$('beginReview').textContent='开始复习（'+reviewSelected.size+' 题）';});
document.addEventListener('click',e=>{const a=e.target.dataset.review;if(!a)return;
if(a==='home'){reviewHome();return;}if(a==='recommend'||a==='list'){reviewList(a==='recommend');return;}
if(a==='replace'){reviewOrder=reviewOrder.slice(2).concat(reviewOrder.slice(0,2));reviewList();return;}
if(a==='begin'){if(!reviewSelected.size)return;reviewQueue=reviewOrder.filter(i=>reviewSelected.has(i));reviewIndex=0;reviewResults=[];reviewQuestion();return;}
if(a==='hint'){reviewHint=true;$('reviewHint').innerHTML='<div class="item"><span class="tag">已使用提示</span><p>'+formattedText(reviewSamples[reviewQueue[reviewIndex]].hint)+'</p></div>';return;}
if(a==='submit'){const answer=$('reviewAnswer').value.trim();if(!answer){$('reviewAnswer').placeholder='请先写下答案或思路，再提交。';$('reviewAnswer').focus();return;}$('reviewAnswer').disabled=true;document.querySelectorAll('[data-review="submit"],[data-review="hint"]').forEach(b=>b.disabled=true);$('reviewFeedback').innerHTML='<div class="item"><span class="tag">示例参考答案</span><p>'+formattedText(reviewSamples[reviewQueue[reviewIndex]].answer)+'</p><div class="notice">尚未连接模型，不会判断你的答案。下面请手动选择一种结果，仅体验记录后的界面。</div><div class="actions"><button data-review="right">演示：'+(reviewHint?'提示后做对':'独立做对')+'</button><button data-review="wrong">演示：仍不会</button><button data-review="unclear">演示：待确认</button></div></div>';$('reviewFeedback').scrollIntoView({block:'nearest'});return;}
if(['right','wrong','unclear'].includes(a)){const result=a==='right'?(reviewHint?'提示后做对':'独立做对'):a==='wrong'?'仍不会':'待确认';reviewResults.push({id:reviewQueue[reviewIndex],result});reviewIndex++;if(reviewIndex<reviewQueue.length){reviewQuestion();return;}reviewShell('本次练习结束 · 演示记录');$('chat').innerHTML='<div class="notice">这些是手动选择的示例结果，未经过模型批阅；刷新页面后不保留。</div><h2>本次练习结束</h2>'+reviewResults.map(r=>'<div class="item"><span class="tag">'+r.result+'</span><p>'+formattedText(reviewSamples[r.id].question)+'</p></div>').join('')+'<button class="primary" data-review="home">返回复习入口</button>';$('chat').scrollTop=0;}
});
// 复习期间关闭题目详情入口，避免提前显示原答案。
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='复习')reviewHome();else{$('toggle').hidden=false;showView(b.dataset.view);}});
$('recent').onclick=()=>{$('toggle').hidden=false;start();};
